            <div className=\"table-toolbar\"><TextInput controlRef={searchRef} className=\"order-search\" placeholder=\"Поиск по номеру, имени или email\" size=\"l\" value={query} onUpdate={setQuery} hasClear startContent={<Icon data={Magnifier} size={17}/>} controlProps={{'aria-label': 'Поиск заказов'}}/><Button view=\"outlined\" size=\"l\" onClick={() => {setDraftPayment(paymentFilter); setDraftMin(minAmount);setDialog('filters');}}><Icon data={Funnel} size={16}/>Фильтры{(paymentFilter "'!== '"'all' || minAmount) && <span className=\"filter-count\">{Number(paymentFilter "'!== '"'all') + Number("'!!minAmount)}</span>}</Button><div className="toolbar-spacer"/><Button className={grouped ? '"'group-button is-on' : 'group-button'} view=\"outlined\" size=\"l\" onClick={() => {setGrouped("'!grouped); setExpanded(true); setRowSelection({});}}><Icon data={Layers} size={16}/><span>По статусу</span><span className={`toggle-indicator ${grouped ? '"'checked' : ''}"'`}/></Button><Button view="outlined" size="l" onClick={() => setDialog('"'columns')}><Icon data={LayoutColumns3} size={16}/><span className=\"columns-button-label\">Колонки</span></Button></div>
