.above-menu.is-compact {padding: var(--g-spacing-3) 0;}
.workspace-picker {display: flex; align-items: center; gap: var(--g-spacing-2); background: var(--g-color-base-background); border: 1px solid var(--g-color-line-generic); padding: var(--g-spacing-3) var(--g-spacing-2); border-radius: var(--g-border-radius-m); margin-bottom: var(--g-spacing-7);}
